          (-(\[Xi]w*mass[MW]^2) + mass[MZ]^2)^2))/((-1 + \[Xi]w)*
        (-1 + \[Xi]z)*(mass[MW]^2 - mass[MZ]^2)) - 
      (\[Xi]z*(((-2 + d)*sorttad[{0, Sqrt[\[Xi]z]*mass[MZ], mass[MW]}, 
            {0, 1, 1}])/(-mass[MW]^2 + \[Xi]z*mass[MZ]^2)^2 - 
         ((-3 + d)*(mass[MW]^2 + \[Xi]z*mass[MZ]^2)*
           sorttad[{0, Sqrt[\[Xi]z]*mass[MZ], mass[MW]}, {1, 1, 1}])/
          (-mass[MW]^2 + \[Xi]z*mass[MZ]^2)^2))/((-1 + \[Xi]w)*(-1 + \[Xi]z)*
        (-mass[MW]^2 + \[Xi]z*mass[MZ]^2)) + 
      (\[Xi]w*\[Xi]z*(((-2 + d)*sorttad[{0, Sqrt[\[Xi]z]*mass[MZ], 
             Sqrt[\[Xi]w]*mass[MW]}, {0, 1, 1}])/(-(\[Xi]w*mass[MW]^2) + 
            \[Xi]z*mass[MZ]^2)^2 - ((-3 + d)*(\[Xi]w*mass[MW]^2 + 
            \[Xi]z*mass[MZ]^2)*sorttad[{0, Sqrt[\[Xi]z]*mass[MZ], 
             Sqrt[\[Xi]w]*mass[MW]}, {1, 1, 1}])/(-(\[Xi]w*mass[MW]^2) + 
            \[Xi]z*mass[MZ]^2)^2))/((-1 + \[Xi]w)*(-1 + \[Xi]z)*
        (-mass[MW]^2 + \[Xi]z*mass[MZ]^2))))/(4096*cw^2*d*Pi^8*sw^4))
